#!/usr/bin/env python3
# Annuaire : design editorial valide par Louis
# Adapte la presentation a l accueil ; donnees et moteur conserves.
from pathlib import Path
import hashlib, json, base64, zlib
ENTRIES = json.loads('[{"path": "annuaire.html", "old_sha256": "09638e799bdcf6d9d63b64a6975028154eaf647663f0861df3bbe7aa4c12bcae", "new_sha256": "18c0dfc22e4b33178607c676b33f6e9e82e8e8180417258117a138755d834e03", "data": ""}, {"path": "assets/annuaire/editorial.css", "old_sha256": null, "new_sha256": "178b0c9d0f43a1abf2670f458d5e823df201645fdaa05c0a5a43b7b371cd32ed", "data": ""}, {"path": "assets/annuaire/tablette.webp", "old_sha256": null, "new_sha256": "489895efe4c18c66aa01689671250921ce4b55f4c1d5e419b3d823d5f5f5183a", "data": ""}]')
root = Path.cwd().resolve()
prepared = []
for entry in ENTRIES:
    path = (root / entry['path']).resolve()
    assert path.is_relative_to(root), entry['path']
    current = hashlib.sha256(path.read_bytes()).hexdigest() if path.exists() else None
    assert current == entry['old_sha256'], 'Concurrent change: ' + entry['path']
    data = zlib.decompress(base64.b64decode(entry['data'], validate=True))
    assert hashlib.sha256(data).hexdigest() == entry['new_sha256']
    prepared.append((path, data))
for path, data in prepared:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
print('Three approved directory design files applied, with tablet illustration.')
